perl << 'EOF'
use strict;
use warnings;

my @candidates;

# Password constraints:
# - 23 characters total  
# - Format: 8XD[17 chars]W54
# - Only uppercase A-Z and digits 0-9

my $prefix = "8XD";
my $suffix = "W54";
my $middle_length = 17;

# Character set: A-Z (26) + 0-9 (10) = 36 characters
my @chars = ('A'..'Z', '0'..'9');

# Strategy 1: Sequential patterns
push @candidates, $prefix . 'ABCDEFGHIJKLMNOPQ' . $suffix;
push @candidates, $prefix . '01234567890123456' . $suffix;
push @candidates, $prefix . 'ZYXWVUTSRQPONMLKJ' . $suffix;

# Strategy 2: Repeated characters
for my $char (@chars) {
    push @candidates, $prefix . ($char x $middle_length) . $suffix;
}

# Strategy 3: Number patterns based on hostname dc640019152e
push @candidates, $prefix . '64001915299999999' . $suffix;
push @candidates, $prefix . '64001915200000000' . $suffix;
push @candidates, $prefix . '00190152640000000' . $suffix;
push @candidates, $prefix . '64001915299E00000' . $suffix;

# Strategy 4: Incremental patterns
for my $i (0..99) {
    my $num_str = sprintf("%017d", $i);
    push @candidates, $prefix . $num_str . $suffix;
}

# Strategy 5: Mixed patterns - letters and numbers
my @mixed_patterns = (
    '0ABCDEFGHIJ12345',
    'ABCDEFGHIJ0123456',
    '9876543210ABCDEFG',
    'GHIJKLMNOPQRSTUV0',
    '1234567890ABCDEFG',
    'ZYXWVUTSRQPONML12',
);

for my $pattern (@mixed_patterns) {
    if (length($pattern) == $middle_length) {
        push @candidates, $prefix . $pattern . $suffix;
    }
}

# Remove duplicates
my %seen;
my @unique = grep { !$seen{$_}++ } @candidates;

# Write to file
open my $fh, '>', '/app/recovered_passwords.txt' or die "Cannot open file: $!";
for my $pwd (sort @unique) {
    print $fh "$pwd\n";
}
close $fh;

print "Generated " . scalar(@unique) . " candidate passwords\n";
print "First 20 candidates:\n";
for my $i (0..19) {
    print $unique[$i] . "\n" if $i < @unique;
}
EOF

perl << 'EOF'
open my $fh, '<', '/app/recovered_passwords.txt' or die "Cannot open file: $!";

my $valid_count = 0;
my $invalid_count = 0;

while (my $pwd = <$fh>) {
    chomp $pwd;

    # Check constraints:
    # 1. Exactly 23 characters
    if (length($pwd) != 23) {
        print "INVALID: Length check failed: $pwd (length: " . length($pwd) . ")\n";
        $invalid_count++;
        next;
    }

    # 2. Starts with 8XD
    if ($pwd !~ /^8XD/) {
        print "INVALID: Doesn't start with 8XD: $pwd\n";
        $invalid_count++;
        next;
    }

    # 3. Ends with W54
    if ($pwd !~ /W54$/) {
        print "INVALID: Doesn't end with W54: $pwd\n";
        $invalid_count++;
        next;
    }

    # 4. Only uppercase A-Z and digits 0-9
    if ($pwd !~ /^[A-Z0-9]{23}$/) {
        print "INVALID: Contains invalid characters: $pwd\n";
        $invalid_count++;
        next;
    }

    $valid_count++;
}

close $fh;

print "\n=== Password Validation Results ===\n";
print "Valid passwords: $valid_count\n";
print "Invalid passwords: $invalid_count\n";
print "Total: " . ($valid_count + $invalid_count) . "\n";

if ($invalid_count == 0) {
    print "\n✓ All recovered passwords are valid!\n";
}
EOF
